let n = 0
const numbers = new ReadableStream<number>({
  pull: (controller) => {
    n = n + 1
    if (n > 5) { controller.close() } else { controller.enqueue(n * n) }
  }
}, { highWaterMark: 1 })
for await (const square of numbers) { console.log("square:", square) }

const printed: string[] = []
const sink = new WritableStream<string>({
  write: (chunk) => { printed.push(chunk) }
})
await source.pipeThrough(upper).pipeTo(sink)

const upper = new TransformStream<string, string>({
  transform: (chunk, controller) => { controller.enqueue(chunk.toUpperCase()) }
})
await source.pipeThrough(upper).pipeTo(sink)

const [rawBranch, decodeBranch] = source.pipeThrough(new CompressionStream("gzip")).tee()
for await (const chunk of decodeBranch.pipeThrough(new DecompressionStream("gzip"))) {
  out = out + dec.decode(chunk)
}

class Greeter extends Readable<string> {
  words: string[] = ["kalimera", "kosme", "apo", "thessaloniki"]
  i: number = 0
  _read() {
    if (this.i >= this.words.length) { this.push(null) }
    else { this.push(this.words[this.i]); this.i = this.i + 1 }
  }
}

